def max_product(arr, n=None):
    """Write a function to find the maximum product formed by multiplying numbers of an increasing subsequence of that array."""
    if arr is None:
        return 0
    values = list(arr)
    if n is not None:
        if n <= 0:
            return 0
        values = values[:n]
    if not values:
        return 0

    max_ending = []
    min_ending = []
    best = values[0]

    for i, value in enumerate(values):
        current_max = value
        current_min = value
        for j in range(i):
            if values[j] < value:
                for candidate in (max_ending[j] * value, min_ending[j] * value):
                    if candidate > current_max:
                        current_max = candidate
                    if candidate < current_min:
                        current_min = candidate
        max_ending.append(current_max)
        min_ending.append(current_min)
        if current_max > best:
            best = current_max

    return best
